/* =====================================================================
   PHÉNIX PDF — charte graphique commune des sorties PDF de la suite Phénix
   (jsPDF 2.5.1, A4 portrait). Charge d'abord jspdf.umd.min.js, puis ce fichier.

   Usage :
     const px = PhenixPDF.create({ titre:'Dossier de synthèse des travaux', sousTitre:'Client · réf.' });
     px.ligne('Client :', 'M. Dupont');
     px.section('Synthèse des travaux');
     px.tableau({ colonnes:[{titre:'Lot',x:17,w:20},{titre:'Montant',x:193,align:'right',w:30,gras:true}],
                  lignes:[['LOT 01','1 000 €']], total:['TOTAL','1 000 €'] });
     px.bloc(['• ligne 1','• ligne 2'], {titre:'Pièces du dossier'});   // jamais coupé par un saut de page
     px.enregistrer('Nom-du-fichier.pdf');

   Règles : voir le skill « phenix-sortie-pdf ». Jamais d'information portée par la couleur seule
   (Maxime est daltonien) : statuts en toutes lettres, en-têtes de tableau en texte blanc gras sur marine.
   ===================================================================== */
(function (global) {
  'use strict';

  var COULEURS = {
    marine:  [10, 22, 40],     // fond bleu nuit (#0a1628) — bandeaux, en-têtes de tableau
    marine2: [16, 31, 56],     // #101f38
    ciel:    [125, 198, 232],  // #7DC6E8 — « -Architecture » du wordmark
    accent:  [79, 168, 240],   // #4fa8f0 — filets
    encre:   [15, 30, 61],     // texte courant sur fond blanc
    titre:   [14, 36, 70],     // titres de section
    discret: [90, 105, 130],   // texte secondaire
    filet:   [200, 212, 226],
    zebre:   [244, 247, 251],
    total:   [225, 236, 248]
  };

  var SOCIETE = {
    nom: 'Phénix-Architecture EURL',
    metiers: 'MAÎTRISE D’ŒUVRE · CONTRACTANT GÉNÉRAL',
    metiersCourt: 'Maîtrise d’œuvre · Contractant général',
    siret: '987 989 316 00011',
    adresse: '6 lieu-dit l’Étreille, 63780 Saint-Georges-de-Mons',
    tel: '04 73 73 00 59',
    mail: 'contact@phenixarchitecte.fr',
    site: 'phenix-architecte.fr'
  };

  var PAGE = { w: 210, h: 297, marge: 15, bas: 272, haut1: 54, haut: 28 };

  var POLICE_TITRE_B64 = '';
  var LOGO_PNG_B64 = '';   // phénix compact, fond transparent (même fichier que le shell)

  function Pdf(opts) {
    opts = opts || {};
    var jsPDF = global.jspdf.jsPDF;
    this.doc = new jsPDF({ unit: 'mm', format: 'a4' });
    this.titre = opts.titre || '';
    this.sousTitre = opts.sousTitre || '';
    this.reference = opts.reference || '';      // affichée dans le pied de page de chaque page
    this.paraphes = !!opts.paraphes;            // cases « Paraphes » en pied de page (documents contractuels)
    this.brouillon = opts.brouillon || '';      // ex. 'PROJET — À COMPLÉTER' : filigrane + mention sur chaque page
    this.serif = false;
    try {
      this.doc.addFileToVFS('DMSerifDisplay-Regular.ttf', POLICE_TITRE_B64);
      this.doc.addFont('DMSerifDisplay-Regular.ttf', 'DMSerif', 'normal');
      this.serif = true;
    } catch (e) { this.serif = false; }
    this.page = 1;
    this._entetePage1();
    this.y = PAGE.haut1;
    this._titreDocument();
  }

  var P = Pdf.prototype;

  P._serif = function (taille) {
    if (this.serif) this.doc.setFont('DMSerif', 'normal'); else this.doc.setFont('times', 'normal');
    this.doc.setFontSize(taille);
  };
  P._sans = function (gras, taille) {
    this.doc.setFont('helvetica', gras ? 'bold' : 'normal');
    if (taille) this.doc.setFontSize(taille);
  };

  /* Wordmark « Phénix-Architecture » (Phénix blanc, -Architecture bleu ciel) */
  P._wordmark = function (x, y, taille, surFondSombre) {
    var d = this.doc;
    this._serif(taille);
    d.setTextColor.apply(d, surFondSombre ? [255, 255, 255] : COULEURS.titre);
    d.text('Phénix', x, y);
    var w = d.getTextWidth('Phénix');
    d.setTextColor.apply(d, surFondSombre ? COULEURS.ciel : COULEURS.accent);
    d.text('-Architecture', x + w, y);
  };

  P._entetePage1 = function () {
    var d = this.doc;
    d.setFillColor.apply(d, COULEURS.marine); d.rect(0, 0, PAGE.w, 42, 'F');
    d.setFillColor.apply(d, COULEURS.accent); d.rect(0, 42, PAGE.w, 1.2, 'F');
    try { d.addImage('data:image/png;base64,' + LOGO_PNG_B64, 'PNG', PAGE.marge, 6, 20.8, 30); } catch (e) {}
    this._wordmark(42, 21, 24, true);
    this._sans(false, 7.5); d.setTextColor.apply(d, COULEURS.ciel);
    if (d.setCharSpace) d.setCharSpace(0.6);
    d.text(SOCIETE.metiers, 42, 28.5);
    if (d.setCharSpace) d.setCharSpace(0);
    this._sans(false, 7.5); d.setTextColor(190, 208, 228);
    var lignes = [SOCIETE.nom + ' · SIRET ' + SOCIETE.siret, SOCIETE.adresse, SOCIETE.tel + ' · ' + SOCIETE.mail, SOCIETE.site];
    for (var i = 0; i < lignes.length; i++) d.text(lignes[i], PAGE.w - PAGE.marge, 13 + i * 4.6, { align: 'right' });
  };

  P._enteteSuite = function () {
    var d = this.doc;
    d.setFillColor.apply(d, COULEURS.marine); d.rect(0, 0, PAGE.w, 15, 'F');
    d.setFillColor.apply(d, COULEURS.accent); d.rect(0, 15, PAGE.w, 0.8, 'F');
    this._wordmark(PAGE.marge, 10, 13, true);
    this._sans(false, 8); d.setTextColor(190, 208, 228);
    d.text(this.titre, PAGE.w - PAGE.marge, 10, { align: 'right' });
  };

  P._titreDocument = function () {
    var d = this.doc;
    this._serif(21); d.setTextColor.apply(d, COULEURS.titre);
    d.text(this.titre, PAGE.marge, this.y);
    this.y += 7;
    if (this.sousTitre) { this._sans(false, 9.5); d.setTextColor.apply(d, COULEURS.discret); d.text(this.sousTitre, PAGE.marge, this.y); this.y += 5; }
    this.y += 5;
    d.setTextColor.apply(d, COULEURS.encre);
  };

  P.nouvellePage = function () {
    this.doc.addPage(); this.page++;
    this._enteteSuite();
    this.y = PAGE.haut;
  };

  /* Garantit qu'un bloc de hauteur h (mm) tient sur la page ; sinon saut de page. */
  P.ensure = function (h) {
    if (this.y + h > PAGE.bas) { this.nouvellePage(); return true; }
    return false;
  };

  P._titreSection = function (titre) {
    var d = this.doc;
    this._serif(13.5); d.setTextColor.apply(d, COULEURS.titre);
    d.text(titre, PAGE.marge, this.y);
    this.y += 2.5;
    d.setDrawColor.apply(d, COULEURS.filet); d.setLineWidth(0.3); d.line(PAGE.marge, this.y, PAGE.w - PAGE.marge, this.y);
    d.setFillColor.apply(d, COULEURS.accent); d.rect(PAGE.marge, this.y - 0.5, 14, 1, 'F');
    this.y += 6.5;
    d.setTextColor.apply(d, COULEURS.encre); this._sans(false, 10);
  };

  /* Titre de section ; réserve au moins hMin mm derrière lui (jamais de titre orphelin). */
  P.section = function (titre, hMin) {
    this.ensure(10 + (hMin || 22));
    this._titreSection(titre);
  };

  P.ligne = function (etiquette, valeur) {
    var d = this.doc;
    this._sans(true, 10); d.setTextColor.apply(d, COULEURS.encre);
    var x = PAGE.marge + d.getTextWidth(etiquette) + 3;
    this._sans(false, 10);
    var lignes = d.splitTextToSize(String(valeur == null || valeur === '' ? '—' : valeur), PAGE.w - PAGE.marge - x);
    this.ensure(6 * lignes.length);
    this._sans(true, 10); d.text(etiquette, PAGE.marge, this.y);
    this._sans(false, 10); d.text(lignes, x, this.y);
    this.y += 6 * lignes.length;
  };

  /* Bloc de lignes insécable : titre + toutes les lignes sur la même page si possible
     (si le bloc dépasse une page entière, il se coupe entre deux lignes, jamais au milieu d'une). */
  P.bloc = function (lignes, opts) {
    opts = opts || {};
    var pas = opts.pas || 6, d = this.doc;
    var h = (opts.titre ? 12 : 0) + lignes.length * pas;
    if (h <= PAGE.bas - PAGE.haut) this.ensure(h); else this.ensure(12 + 3 * pas);
    if (opts.titre) this._titreSection(opts.titre);
    this._sans(false, opts.taille || 10); d.setTextColor.apply(d, COULEURS.encre);
    for (var i = 0; i < lignes.length; i++) {
      var l = lignes[i];
      var txt = typeof l === 'string' ? l : l.texte;
      var droite = typeof l === 'string' ? null : l.droite;
      this.ensure(pas);
      this._sans(false, opts.taille || 10); d.text(txt, opts.x || 20, this.y);
      if (droite) { this._sans(true, opts.taille || 10); d.text(droite, opts.xDroite || 180, this.y, { align: 'right' }); }
      this.y += pas;
    }
    this.y += 4;
  };

  /* Paragraphe (texte libre) : coupé uniquement entre deux lignes. */
  P.paragraphe = function (texte, opts) {
    opts = opts || {};
    var d = this.doc, x = opts.x || 20, w = opts.w || 170, pas = opts.pas || 5;
    this._sans(false, opts.taille || 10); d.setTextColor.apply(d, COULEURS.encre);
    var lignes = d.splitTextToSize(String(texte), w);
    for (var i = 0; i < lignes.length; i++) { this.ensure(pas); d.text(lignes[i], x, this.y); this.y += pas; }
    this.y += 3;
  };

  /* Tableau : en-tête répété à chaque page, lignes jamais coupées, total toujours avec
     au moins deux lignes au-dessus de lui. colonnes: [{titre,x,align,w,gras}] ; x = position du texte
     (pour align:'right', x = bord droit). */
  P.tableau = function (cfg) {
    var d = this.doc, cols = cfg.colonnes, self = this, pas = 4.4, pad = 2.2;
    function entete() {
      self.ensure(18);
      d.setFillColor.apply(d, COULEURS.marine); d.rect(PAGE.marge, self.y - 4.6, PAGE.w - 2 * PAGE.marge, 7.2, 'F');
      self._sans(true, 8.5); d.setTextColor(255, 255, 255);
      cols.forEach(function (c) { d.text(c.titre, c.x, self.y, c.align ? { align: c.align } : undefined); });
      self.y += 6.2;
    }
    entete();
    var lignes = cfg.lignes, n = lignes.length;
    for (var i = 0; i < n; i++) {
      var cellules = lignes[i], hauteurs = 1, mises = [];
      this._sans(false, 9);
      cols.forEach(function (c, k) {
        var txt = String(cellules[k] == null ? '' : cellules[k]);
        var l = c.w ? d.splitTextToSize(txt, c.w) : [txt];
        mises.push(l); if (l.length > hauteurs) hauteurs = l.length;
      });
      var h = hauteurs * pas + pad;
      var reserve = (cfg.total && i >= n - 2) ? h + (n - 1 - i) * 8 + 12 : h;   // dernières lignes + total ensemble
      if (this.y - 4.6 + reserve > PAGE.bas) { this.nouvellePage(); entete(); }
      if (i % 2 === 0) { d.setFillColor.apply(d, COULEURS.zebre); d.rect(PAGE.marge, this.y - 3.6, PAGE.w - 2 * PAGE.marge, h, 'F'); }
      d.setTextColor.apply(d, COULEURS.encre);
      cols.forEach(function (c, k) {
        self._sans(!!c.gras, 9);
        d.text(mises[k], c.x, self.y, c.align ? { align: c.align } : undefined);
      });
      this.y += h;
    }
    if (cfg.total) {
      this.ensure(12);
      d.setFillColor.apply(d, COULEURS.total); d.rect(PAGE.marge, this.y - 3.6, PAGE.w - 2 * PAGE.marge, 8, 'F');
      d.setDrawColor.apply(d, COULEURS.marine); d.setLineWidth(0.5); d.line(PAGE.marge, this.y - 3.6, PAGE.w - PAGE.marge, this.y - 3.6);
      d.setTextColor.apply(d, COULEURS.titre);
      cols.forEach(function (c, k) {
        var t = cfg.total[k]; if (t == null || t === '') return;
        self._sans(true, 10); d.text(String(t), c.x, self.y + 1.4, c.align ? { align: c.align } : undefined);
      });
      this.y += 11;
    }
    d.setTextColor.apply(d, COULEURS.encre); this._sans(false, 10);
    this.y += 3;
  };


  /* ═══ Documents contractuels : articles, texte riche, cadres, signatures ═══ */

  /* Découpe un texte contenant des **passages en gras** en lignes de largeur w (mm). */
  P._lignesRiches = function (texte, w, taille) {
    var d = this.doc, mots = [], gras = false;
    String(texte).split(/(\*\*)/).forEach(function (seg) {
      if (seg === '**') { gras = !gras; return; }
      seg.split(/(\s+)/).forEach(function (m) { if (m !== '' && !/^\s+$/.test(m)) mots.push({ t: m, b: gras }); else if (/^\s+$/.test(m)) mots.push({ t: ' ', b: gras, esp: true }); });
    });
    var lignes = [], cur = [], largeur = 0, self = this;
    function mesure(mot) { self._sans(mot.b, taille); return d.getTextWidth(mot.t); }
    mots.forEach(function (mot) {
      if (mot.esp) { if (cur.length) { var we = mesure(mot); cur.push(mot); largeur += we; } return; }
      var wm = mesure(mot);
      if (largeur + wm > w && cur.length) {
        while (cur.length && cur[cur.length - 1].esp) cur.pop();
        lignes.push(cur); cur = []; largeur = 0;
      }
      cur.push(mot); largeur += wm;
    });
    while (cur.length && cur[cur.length - 1].esp) cur.pop();
    if (cur.length) lignes.push(cur);
    return lignes;
  };
  P._ligneRiche = function (ligne, x, y, taille) {
    var d = this.doc, cx = x;
    for (var i = 0; i < ligne.length; i++) {
      this._sans(ligne[i].b, taille); d.text(ligne[i].t, cx, y); cx += d.getTextWidth(ligne[i].t);
    }
  };

  /* Titre d'article : jamais seul en bas de page (réserve de quoi écrire au moins 3 lignes derrière). */
  P.article = function (titre, reserve) {
    this.ensure(reserve || 26);
    var d = this.doc;
    this.y += 2;
    this._serif(11.5); d.setTextColor.apply(d, COULEURS.titre);
    d.text(titre, PAGE.marge, this.y);
    this.y += 1.8;
    d.setDrawColor.apply(d, COULEURS.filet); d.setLineWidth(0.25); d.line(PAGE.marge, this.y, PAGE.w - PAGE.marge, this.y);
    this.y += 5;
    d.setTextColor.apply(d, COULEURS.encre); this._sans(false, 9.5);
  };

  /* Paragraphe avec gras **...**, sans ligne veuve ni orpheline. */
  P.texte = function (texte, opts) {
    opts = opts || {};
    var x = opts.x || PAGE.marge, w = opts.w || (PAGE.w - PAGE.marge - x), taille = opts.taille || 9.5, pas = opts.pas || 4.7;
    var d = this.doc; d.setTextColor.apply(d, COULEURS.encre);
    var lignes = this._lignesRiches(texte, w, taille), n = lignes.length;
    for (var i = 0; i < n; i++) {
      if (i === 0) this.ensure(Math.min(n, 2) * pas + (opts.suite || 0)); else if (i === n - 2 && n > 3) this.ensure(2 * pas); else this.ensure(pas);
      d.setTextColor.apply(d, COULEURS.encre);
      this._ligneRiche(lignes[i], x, this.y, taille); this.y += pas;
    }
    this.y += opts.apres == null ? 1.8 : opts.apres;
  };

  /* Liste à puces (texte riche), chaque puce insécable. */
  P.puces = function (items, opts) {
    opts = opts || {};
    var taille = opts.taille || 9.5, pas = opts.pas || 4.7, d = this.doc, x0 = PAGE.marge + 3, w = PAGE.w - PAGE.marge - x0 - 4;
    for (var k = 0; k < items.length; k++) {
      var lignes = this._lignesRiches(items[k], w, taille);
      this.ensure(Math.min(lignes.length, 3) * pas);
      d.setFillColor.apply(d, COULEURS.accent); d.circle(x0 + 0.6, this.y - 1.2, 0.55, 'F');
      for (var i = 0; i < lignes.length; i++) {
        if (i > 0 && i === lignes.length - 1 && lignes.length > 2) this.ensure(pas);
        else if (i > 0) this.ensure(pas);
        d.setTextColor.apply(d, COULEURS.encre); this._ligneRiche(lignes[i], x0 + 4, this.y, taille); this.y += pas;
      }
      this.y += 0.6;
    }
    this.y += 1.5;
  };

  /* Cases à cocher : [{texte, coche}] — une case cochée porte une croix ET le mot dans le texte n'est pas nécessaire (forme lisible sans couleur). */
  P.cases = function (items, opts) {
    opts = opts || {};
    var d = this.doc, pas = opts.pas || 5.6, taille = opts.taille || 9.5;
    for (var i = 0; i < items.length; i++) {
      var it = items[i], w = PAGE.w - PAGE.marge - 30;
      var lignes = this._lignesRiches(it.texte, w, taille);
      this.ensure(lignes.length * 4.7 + 2);
      var y0 = this.y;
      d.setDrawColor.apply(d, COULEURS.marine); d.setLineWidth(0.35); d.rect(PAGE.marge + 3, y0 - 3.3, 3.8, 3.8);
      if (it.coche) { d.setLineWidth(0.7); d.line(PAGE.marge + 3.5, y0 - 2.8, PAGE.marge + 6.3, y0 - 0.1); d.line(PAGE.marge + 6.3, y0 - 2.8, PAGE.marge + 3.5, y0 - 0.1); }
      for (var k = 0; k < lignes.length; k++) { d.setTextColor.apply(d, COULEURS.encre); this._ligneRiche(lignes[k], PAGE.marge + 10, this.y, taille); this.y += 4.7; }
      this.y += pas - 4.7;
    }
    this.y += 1.5;
  };

  /* Cadre(s) d'identification : une ou deux colonnes ; chaque cadre = {titre, lignes:[…]} (gras **…** accepté). */
  P.cadres = function (liste) {
    var d = this.doc, n = liste.length, gap = 4, larg = (PAGE.w - 2 * PAGE.marge - gap * (n - 1)) / n, taille = 9, pas = 4.4, self = this;
    var mises = liste.map(function (c) { return c.lignes.map(function (l) { return self._lignesRiches(l, larg - 7, taille); }); });
    var hauteur = Math.max.apply(null, mises.map(function (m) { return 9 + m.reduce(function (s, l) { return s + l.length; }, 0) * pas + 3; }));
    this.ensure(hauteur + 3);
    var y0 = this.y - 4;
    liste.forEach(function (c, k) {
      var x = PAGE.marge + k * (larg + gap);
      d.setFillColor.apply(d, COULEURS.zebre); d.setDrawColor.apply(d, COULEURS.filet); d.setLineWidth(0.3); d.roundedRect(x, y0, larg, hauteur, 1.5, 1.5, 'FD');
      self._sans(true, 7.5); d.setTextColor.apply(d, COULEURS.discret); d.text(String(c.titre).toUpperCase(), x + 3.5, y0 + 5);
      var y = y0 + 10;
      mises[k].forEach(function (lg) { lg.forEach(function (l) { d.setTextColor.apply(d, COULEURS.encre); self._ligneRiche(l, x + 3.5, y, taille); y += pas; }); });
    });
    this.y = y0 + hauteur + 5;
    d.setTextColor.apply(d, COULEURS.encre);
  };

  /* Chiffres clés : [{etiquette, valeur, detail}] sur une ligne. */
  P.cles = function (items) {
    var d = this.doc, n = items.length, gap = 4, larg = (PAGE.w - 2 * PAGE.marge - gap * (n - 1)) / n, h = 19;
    this.ensure(h + 4);
    var y0 = this.y - 4;
    for (var i = 0; i < n; i++) {
      var x = PAGE.marge + i * (larg + gap);
      d.setFillColor.apply(d, COULEURS.zebre); d.setDrawColor.apply(d, COULEURS.filet); d.roundedRect(x, y0, larg, h, 1.5, 1.5, 'FD');
      this._sans(true, 7); d.setTextColor.apply(d, COULEURS.discret); d.text(String(items[i].etiquette).toUpperCase(), x + 3.5, y0 + 5);
      this._sans(true, 11.5); d.setTextColor.apply(d, COULEURS.titre); d.text(String(items[i].valeur), x + 3.5, y0 + 11.5);
      if (items[i].detail) { this._sans(false, 7.5); d.setTextColor.apply(d, COULEURS.discret); d.text(String(items[i].detail), x + 3.5, y0 + 16); }
    }
    this.y = y0 + h + 6; d.setTextColor.apply(d, COULEURS.encre);
  };

  /* Bloc de signatures (insécable) : [{titre, qualite, mention}] ; zones Nom/Lieu et date/Signature à remplir à la main. */
  P.signatures = function (blocs) {
    var d = this.doc, n = blocs.length, gap = 4, larg = (PAGE.w - 2 * PAGE.marge - gap * (n - 1)) / n, h = 46;
    this.ensure(h + 8);
    var y0 = this.y - 2;
    for (var i = 0; i < n; i++) {
      var x = PAGE.marge + i * (larg + gap), b = blocs[i];
      d.setDrawColor.apply(d, COULEURS.marine); d.setLineWidth(0.4); d.roundedRect(x, y0, larg, h, 1.5, 1.5, 'S');
      this._sans(true, 8.5); d.setTextColor.apply(d, COULEURS.titre);
      var tl = d.splitTextToSize(b.titre, larg - 7); d.text(tl, x + 3.5, y0 + 5.5);
      var yy = y0 + 5.5 + tl.length * 3.8;
      if (b.qualite) { this._sans(false, 7.8); d.setTextColor.apply(d, COULEURS.discret); var ql = d.splitTextToSize(b.qualite, larg - 7); d.text(ql, x + 3.5, yy); yy += ql.length * 3.4; }
      this._sans(false, 7.2); d.setTextColor.apply(d, COULEURS.discret);
      d.text('Nom, prénom, qualité :', x + 3.5, y0 + h - 25);
      d.text('Lieu et date :', x + 3.5, y0 + h - 17.5);
      d.text(larg < 70 ? 'Signature (« Lu et approuvé ») :' : 'Signature précédée de « Lu et approuvé, bon pour accord » :', x + 3.5, y0 + h - 10);
      d.setDrawColor.apply(d, COULEURS.filet); d.setLineWidth(0.2);
      d.line(x + 3.5, y0 + h - 23.3, x + larg - 3.5, y0 + h - 23.3); d.line(x + 3.5, y0 + h - 15.8, x + larg - 3.5, y0 + h - 15.8);
    }
    this.y = y0 + h + 6; d.setTextColor.apply(d, COULEURS.encre);
  };

  P.saut = function () { this.nouvellePage(); };

  /* Filigrane + mention « brouillon » (appelés depuis _pieds) */
  P._filigrane = function (texte) {
    var d = this.doc;
    try {
      d.saveGraphicsState && d.saveGraphicsState();
      d.setGState(new d.GState({ opacity: 0.09 }));
      this._serif(46); d.setTextColor(10, 22, 40);
      d.text(texte, PAGE.w / 2, 160, { align: 'center', angle: 35 });
      d.restoreGraphicsState && d.restoreGraphicsState();
    } catch (e) {}
    d.setGState && d.setGState(new d.GState({ opacity: 1 }));
  };

  P._pieds = function () {
    var d = this.doc, n = d.internal.getNumberOfPages();
    for (var i = 1; i <= n; i++) {
      d.setPage(i);
      d.setDrawColor.apply(d, COULEURS.filet); d.setLineWidth(0.3); d.line(PAGE.marge, 279, PAGE.w - PAGE.marge, 279);
      this._sans(false, 7.2); d.setTextColor.apply(d, COULEURS.discret);
      d.text(SOCIETE.nom + ' · ' + SOCIETE.metiersCourt + ' · SIRET ' + SOCIETE.siret, PAGE.w / 2, 284, { align: 'center' });
      d.text(SOCIETE.adresse + ' · ' + SOCIETE.tel + ' · ' + SOCIETE.mail, PAGE.w / 2, 288, { align: 'center' });
      this._sans(true, 7.5); d.text('Page ' + i + ' / ' + n, PAGE.w - PAGE.marge, 288, { align: 'right' });
      if (this.reference) { this._sans(false, 7); d.setTextColor.apply(d, COULEURS.discret); d.text('Réf. ' + this.reference, PAGE.w - PAGE.marge, 293, { align: 'right' }); }
      if (this.paraphes) {
        this._sans(false, 6.8); d.setTextColor.apply(d, COULEURS.discret);
        d.text('Paraphes :', PAGE.marge, 293);
        d.setDrawColor.apply(d, COULEURS.filet); d.setLineWidth(0.25);
        d.rect(PAGE.marge + 14, 289.6, 14, 4.6); d.rect(PAGE.marge + 30, 289.6, 14, 4.6);
      }
      if (this.brouillon) {
        this._sans(true, 8); d.setTextColor.apply(d, COULEURS.titre);
        d.text(this.brouillon, PAGE.w / 2, 275.5, { align: 'center' });
        this._filigrane(this.brouillon.split(' — ')[0]);
      }
    }
  };

  P.enregistrer = function (nomFichier) {
    this._pieds();
    this.doc.save(nomFichier);
  };

  global.PhenixPDF = {
    couleurs: COULEURS,
    societe: SOCIETE,
    page: PAGE,
    create: function (opts) { return new Pdf(opts); }
  };
})(window);
